<div class="page-head"><div><span class="eyebrow dark"><?= e(tr('تعرفه و سرعت', 'Pricing and speed')) ?></span><h1><?= e(tr('پلن‌ها', 'Plans')) ?></h1><p><?= e(tr('پلن‌های فروش، محدودیت‌ها و پروفایل‌های User Manager', 'User Manager profiles and limitations')) ?></p></div><?php if(Auth::canWrite()):?><a class="button primary" href="<?= e(url('plan-form')) ?>">＋ <?= e(tr('پلن جدید','New plan')) ?></a><?php endif;?></div>
<section class="card-grid">
<?php foreach($plans as $plan):?><article class="plan-card <?= $plan['is_active']?'':'disabled-card' ?>"><div class="plan-top"><span class="plan-icon">◇</span><span class="badge <?= $plan['is_active']?'success':'muted' ?>"><?= $plan['is_active']?e(tr('فعال','Active')):e(tr('غیرفعال','Inactive')) ?></span></div><h2><?= e($plan['name']) ?></h2><div class="plan-price"><strong><?= fa_digits(number_format((float)$plan['price'],0)) ?></strong><small><?= e($plan['currency']) ?> / <?= fa_digits($plan['validity_days']) ?> <?= e(tr('روز','days')) ?></small></div><dl><div><dt><?= e(tr('پروفایل User Manager','User Manager profile')) ?></dt><dd dir="ltr"><?= e($plan['mikrotik_profile']) ?></dd></div><div><dt><?= e(tr('محدودیت سرعت','Rate limit')) ?></dt><dd dir="ltr"><?= e($plan['rate_limit']) ?></dd></div><div><dt><?= e(tr('حجم','Data cap')) ?></dt><dd><?= $plan['data_cap_gb']?fa_digits($plan['data_cap_gb']).' GB':e(tr('نامحدود','Unlimited')) ?></dd></div><div><dt><?= e(tr('کاربران','Users')) ?></dt><dd><?= fa_digits($plan['user_count']) ?></dd></div></dl><?php if(Auth::canWrite()):?><div class="plan-actions"><a class="button ghost small" href="<?= e(url('plan-form',['id'=>$plan['id']])) ?>"><?= e(tr('ویرایش','Edit')) ?></a><form method="post" action="<?= e(url('plan-delete')) ?>" data-confirm="<?= e(tr('این پلن حذف شود؟ کاربران فعلی بدون پلن می‌مانند.','Delete this plan? Existing users will have no plan.')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($plan['id']) ?>"><button class="button danger-text small"><?= e(tr('حذف','Delete')) ?></button></form></div><?php endif;?></article><?php endforeach;?>
<?php if(!$plans):?><div class="panel empty-state"><span>◇</span><h2><?= e(tr('هنوز پلنی ندارید','No plans yet')) ?></h2><p><?= e(tr('اولین پلن را مطابق نام پروفایل روی روتر بسازید.','Create a plan matching a profile name on your router.')) ?></p></div><?php endif;?>
